let activeBoilerLayers=new Set(),activeBoilerFault='',boilerFaultGroup='Todas';
function currentBoilerFault(){return boilerFaults.find(f=>f.id===activeBoilerFault)}
function boilerFaultAffected(id){return currentBoilerFault()?.parts.includes(id)||false}
function boilerSystemReference(id){if(['feedPump','feedValve'].includes(id))return boilerSystemSources.feed;const layer=Object.values(boilerLayers).find(l=>l.ids.includes(id));return layer?boilerSystemSources[layer.source]:null}
function boilerReferenceLink(key){const [name,url]=boilerSystemSources[key];return `<a href="${url}" target="_blank" rel="noopener">${name} ↗</a>`}
function boilerSystemsPanel(){
 const f=currentBoilerFault();
 return `<section class="boiler-systems" aria-labelledby="systems-title"><div class="eyebrow">AMPLIÁ EL MODELO</div><h2 id="systems-title">Circuitos, controles y fallas</h2><p>Activá las capas de abajo. Después elegí una falla para señalar las zonas afectadas en rojo y explicar qué está pasando.</p>
 <div class="boiler-layer-list">${Object.entries(boilerLayers).map(([id,l])=>`<label><input type="checkbox" data-boiler-layer="${id}" ${activeBoilerLayers.has(id)?'checked':''}><span>${l.name}</span></label>`).join('')}</div>
 <p class="system-note">Accesorios y trazados funcionales esquemáticos, aplicables al estudio de las cuatro vistas; no reproducen el equipamiento exacto de cada fabricante. La capa de control representa funciones modernas genéricas. Para seguir sus señales hacia los actuadores, activá también combustible y alimentación y elegí «Señales de control» en Recorrido. Las flechas de combustible siguen sólo el ramal principal; retorno y redundancias no se dibujan.</p>
 <div class="fault-heading"><h3>Elegir una falla</h3><label>Filtrar por sistema <select id="boiler-fault-group">${['Todas','Combustión','Agua','Control','Auxiliares'].map(g=>`<option ${g===boilerFaultGroup?'selected':''}>${g}</option>`).join('')}</select></label><button id="boiler-fault-clear" class="secondary" ${f?'':'disabled'}>Quitar falla</button></div>
 <div class="boiler-fault-layout"><div class="boiler-fault-list" aria-label="Fallas disponibles">${boilerFaults.filter(item=>boilerFaultGroup==='Todas'||item.group===boilerFaultGroup).map(item=>`<button data-boiler-fault="${item.id}" aria-pressed="${item.id===activeBoilerFault}"><small>${item.group}</small>${item.name}</button>`).join('')}</div>
 <article class="boiler-fault-detail" aria-live="polite">${f?`<span class="fault-pill">CASO DE ESTUDIO · ${f.group}</span><h3>${f.name}</h3><h4>Qué podés observar</h4><p>${f.symptom}</p><h4>Por qué ocurre / cómo afecta</h4><p>${f.cause}</p><h4>Qué tenés que distinguir al explicarlo</h4><p>${f.check}</p><h4>Dónde afecta</h4><div class="fault-targets">${boilerFaultParts(f,model).map(id=>`<button class="secondary" data-fault-part="${id}">${part(id)[0]} ↗</button>`).join('')}</div>${f.parts.length?'<button id="boiler-fault-view" class="secondary">Ver zonas rojas en el modelo ↑</button>':'<p>Ubicación: circuito externo de lubricación, señalado en el esquema inferior.</p>'}<p class="part-reference">${boilerReferenceLink(f.source)}</p>`:'<h3>Relacioná síntoma, causa y componente.</h3><p>Elegí un caso de la lista. Se añadirán las capas necesarias y se marcarán las piezas afectadas. Los colores señalan zonas de estudio: no simulan una medición ni confirman un diagnóstico.</p>'}</article></div>
 <details class="auxiliary-map" ${f?.aux?.length?'open':''}><summary>Circuitos externos: condensado, alimentación y lubricación</summary><p>Fuera de la caldera. Cada recuadro rojo identifica dónde se estudia la falla seleccionada.</p><div class="aux-flow" aria-label="Circuito agua y vapor">${[['turbine','Turbina de vapor'],['condenser','Condensador'],['condensate','Bomba de condensado'],['tank','Tanque / desaireador'],['feedAux','Bomba de alimentación'],['boiler','Caldera → vapor a turbina']].map(([id,name])=>`<span class="${f?.aux?.includes(id)?'affected':''}">${name}${f?.aux?.includes(id)?'<b>Zona afectada</b>':''}</span>`).join('<i aria-hidden="true">→</i>')}</div><div class="aux-flow" aria-label="Circuito de lubricación independiente">${[['oilTank','Tanque de aceite'],['oilPump','Bomba de aceite'],['oilCooler','Filtro / enfriador'],['bearings','Cojinetes'],['return','Retorno al tanque']].map(([id,name])=>`<span class="${f?.aux?.includes(id)?'affected':''}">${name}${f?.aux?.includes(id)?'<b>Zona afectada</b>':''}</span>`).join('<i aria-hidden="true">→</i>')}</div><p>El circuito de aceite lubrica equipos rotativos; no forma parte del agua/vapor ni se mezcla con ella. Orden de filtro/enfriador y protecciones según instalación.</p></details>
 <p class="system-note">Las fichas sirven para reconocer y explicar mecanismos. Las maniobras, límites, ajustes y tratamiento químico corresponden al manual específico de la instalación.</p></section>`;
}
function selectBoilerFault(id){
 activeBoilerFault=id;const f=currentBoilerFault();if(f){f.layers.forEach(k=>activeBoilerLayers.add(k));mode='explore';focusPart=false;explode=0;const ids=boilerFaultParts(f,model);selected=ids[0]||'upper';cutaway=ids.some(k=>internalParts.has(k));flowKind=f.group==='Combustión'?'fuel':'water';flow=true;}
 geometryKey='';renderWorkshop();
}
function bindBoilerSystems(){
 document.querySelectorAll('[data-boiler-layer]').forEach(input=>input.onchange=()=>{const k=input.dataset.boilerLayer;input.checked?activeBoilerLayers.add(k):activeBoilerLayers.delete(k);if(!input.checked&&currentBoilerFault()?.layers.includes(k))activeBoilerFault='';for(const id of [...placed])if(!partIds().includes(id))placed.delete(id);if(flowKind==='fuel'&&!activeBoilerLayers.has('fuel'))flowKind='water';geometryKey='';renderWorkshop()});
 document.querySelectorAll('[data-boiler-fault]').forEach(b=>b.onclick=()=>selectBoilerFault(b.dataset.boilerFault));
 document.querySelector('#boiler-fault-group').onchange=e=>{boilerFaultGroup=e.target.value;renderWorkshop()};
 document.querySelector('#boiler-fault-clear').onclick=()=>selectBoilerFault('');
 document.querySelector('#boiler-fault-view')?.addEventListener('click',()=>document.querySelector('.viewport').scrollIntoView({behavior:'smooth',block:'start'}));
 document.querySelectorAll('[data-fault-part]').forEach(b=>b.onclick=()=>{selected=b.dataset.faultPart;focusPart=false;if(internalParts.has(selected))cutaway=true;document.querySelector('#cut-toggle').setAttribute('aria-pressed',String(cutaway));document.querySelector('#focus-toggle').setAttribute('aria-pressed','false');updateParts();document.querySelector('.viewport').scrollIntoView({behavior:'smooth',block:'start'})});
}
